components.css:
.ds-system{--ob-battery:var(--energy-battery-out-color,#00a99a);--ob-secondary:var(--secondary-text-color,#687080);--ob-line:var(--divider-color,#e2e5eb);font-family:var(--ha-font-family-body,var(--paper-font-body1_-_font-family,Roboto,Arial,sans-serif));font-size:14px;line-height:1.45;font-variant-numeric:tabular-nums;color:var(--primary-text-color,#202530);padding:20px;border:var(--ha-card-border-width,1px) solid var(--ha-card-border-color,var(--ob-line));border-radius:var(--ha-card-border-radius,12px);background:var(--ha-card-background,var(--card-background-color,#fff));box-shadow:none;overflow:hidden}.ds-system-container{container-type:inline-size;min-width:0}.ds-ob-header{display:flex;justify-content:space-between;gap:12px}.ds-system h2{margin:0;font-size:18px;line-height:1.3;font-weight:600;letter-spacing:-.2px;overflow-wrap:anywhere}.ds-subtitle{color:var(--ob-secondary);font-size:12px}.ds-system-icon svg{fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}@media(max-width:450px){.ds-system{padding:16px}.ds-system h2{font-size:17px}}
    .ds-ob-header { align-items: baseline; margin-bottom: 21px; }
    .ds-ob-header .ds-subtitle { flex: none; white-space: nowrap; }
    .ds-system-summary { display: grid; grid-template-columns: 52px minmax(0, 1fr); align-items: center; gap: 14px; margin: 0 0 21px; }
    .ds-system-icon { display: grid; place-items: center; width: 52px; height: 52px; border-radius: 50%; color: var(--ob-battery); background: color-mix(in srgb, var(--ob-battery) 12%, transparent); }
    .ds-system-icon svg { width: 29px; height: 29px; }
    .ds-system-values { min-width: 0; }
    .ds-system-heading { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: baseline; gap: 3px 10px; margin-bottom: 9px; }
    .ds-system-reading { display: flex; align-items: baseline; flex-wrap: wrap; gap: 3px 7px; }
    .ds-system-soc { font-size: 24px; line-height: 1.25; font-weight: 600; color: var(--primary-text-color, #17202c); white-space: nowrap; }
    .ds-stored { color: var(--ob-secondary); font-size: 12px; line-height: 1.5; overflow-wrap: anywhere; }
    .ds-unavailable { color: var(--ob-secondary); font-size: 11px; line-height: 1.5; }
    .ds-system button { padding: 0; border: 0; border-radius: 3px; background: transparent; text-align: left; font: inherit; cursor: pointer; }
    .ds-system button:hover { text-decoration: underline; text-underline-offset: 3px; }
    .ds-system button:focus-visible { outline: 2px solid var(--primary-color, #03a9f4); outline-offset: 4px; }
    .ds-meter { position: relative; width: 100%; overflow: hidden; border-radius: 5px; background: var(--disabled-color, #dce1e6); }
    .ds-meter-fill { height: 100%; border-radius: inherit; background: var(--ob-battery); }
    .ds-system-meter { height: 9px; }
    .ds-battery-meter { height: 5px; }
    .ds-is-unavailable .ds-meter-fill { background: transparent; }
    .ds-battery-list { display: grid; margin: 0; padding: 20px 0 0; list-style: none; border-top: 1px solid var(--ob-line); }
    .ds-battery-item { min-width: 0; }
    .ds-battery-name { min-width: 0; color: var(--ob-secondary); font-size: 12px; line-height: 1.5; overflow-wrap: anywhere; }
    .ds-battery-reading { display: flex; flex-wrap: wrap; align-items: baseline; gap: 2px 6px; }
    .ds-battery-soc { font-size: 20px; line-height: 1.3; font-weight: 600; color: var(--primary-text-color, #17202c); white-space: nowrap; }
    .ds-system[data-layout="columns"] .ds-battery-list { grid-template-columns: repeat(var(--battery-columns, 3), minmax(0, 1fr)); gap: 22px 24px; }
    .ds-system[data-layout="columns"] .ds-battery-item { position: relative; display: flex; flex-direction: column; }
    .ds-system[data-layout="columns"] .ds-battery-item:not(.ds-first-column)::before { content: ''; position: absolute; left: -12px; top: 0; bottom: 0; border-left: 1px solid var(--ob-line); }
    .ds-system[data-layout="columns"] .ds-battery-name { margin-bottom: 7px; }
    .ds-system[data-layout="columns"] .ds-battery-reading { margin-top: auto; }
    .ds-system[data-layout="columns"] .ds-battery-meter { margin-top: 10px; }
    .ds-system[data-layout="stacked"] .ds-battery-list { grid-template-columns: minmax(0, 1fr); gap: 21px; }
    .ds-system[data-layout="stacked"] .ds-battery-item { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: baseline; gap: 7px 12px; }
    .ds-system[data-layout="stacked"] .ds-battery-name { color: var(--primary-text-color, #17202c); font-size: 14px; }
    .ds-system[data-layout="stacked"] .ds-battery-reading { justify-content: flex-end; max-width: 100px; }
    .ds-system[data-layout="stacked"] .ds-battery-soc { font-size: 15px; font-weight: 500; }
    .ds-system[data-layout="stacked"] .ds-battery-meter { grid-column: 1 / -1; }
    .ds-compact-header { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 12px; margin-bottom: 17px; }
    .ds-compact-title { min-width: 0; }
    .ds-compact-title h2 { margin-bottom: 3px; }
    .ds-compact-header .ds-system-reading { justify-content: flex-end; max-width: 108px; }
    .ds-system[data-layout="compact"] .ds-battery-list { grid-template-columns: minmax(0, 1fr); gap: 13px; padding-top: 17px; }
    .ds-system[data-layout="compact"] .ds-battery-item { display: grid; grid-template-columns: minmax(0, 1fr) minmax(30px, 1.6fr) minmax(40px, auto); align-items: center; gap: 12px; }
    .ds-system[data-layout="compact"] .ds-battery-name { color: var(--primary-text-color, #17202c); font-size: 13px; }
    .ds-system[data-layout="compact"] .ds-battery-meter { grid-column: 2; grid-row: 1; }
    .ds-system[data-layout="compact"] .ds-battery-reading { grid-column: 3; grid-row: 1; justify-content: flex-end; max-width: 76px; }
    .ds-system[data-layout="compact"] .ds-battery-soc { font-size: 14px; font-weight: 500; }
    .ds-empty { margin: 0; border-top: 1px solid var(--ob-line); padding-top: 17px; color: var(--ob-secondary); font-size: 13px; line-height: 1.6; }
    @container (max-width: 350px) {
      .ds-system-summary { grid-template-columns: 46px minmax(0, 1fr); gap: 11px; }
      .ds-system-icon { width: 46px; height: 46px; }
      .ds-system-icon svg { width: 26px; height: 26px; }
      .ds-system-heading { gap: 3px 7px; }
      .ds-stored { font-size: 11px; }
      .ds-system[data-layout="columns"] .ds-battery-list { column-gap: 20px; }
      .ds-system[data-layout="columns"] .ds-battery-item:not(.ds-first-column)::before { left: -10px; }
      .ds-system[data-layout="compact"] .ds-battery-item { gap: 9px; }
    }
